import unicodedata


def display_width(text: str) -> int:
    total = 0
    for ch in text:
        category = unicodedata.category(ch)
        if category in ('Mn', 'Me', 'Cf'):
            continue
        if unicodedata.east_asian_width(ch) in ('W', 'F'):
            total += 2
        else:
            total += 1
    return total
